<?php

declare(strict_types=1);

namespace FastWebsite\Validation;

use FastWebsite\Repositories\PublicationRepository;

final class PublicationValidator
{
    private const ACCESS=['open_access','subscription','restricted','unknown'];
    public function __construct(private readonly PublicationRepository$publications){}
    /** @param array<string,string|null> $input @return array{data:array<string,mixed>,project_id:?int,research_unit_id:?int,errors:list<string>} */ public function validate(array$input,?int$existingId=null):array{$errors=[];$type=$this->id($input['publication_type_id']??null);$title=trim((string)($input['title']??''));$slug=strtolower(trim((string)($input['slug']??'')));if($slug==='')$slug=$this->slugify($title);$project=$this->id($input['project_id']??null);$unit=$this->id($input['research_unit_id']??null);if($type===null||!$this->publications->relationExists('publication_types',$type))$errors[]='Select a valid publication type.';if($title===''||mb_strlen($title)>5000)$errors[]='Publication title is required.';if($slug===''||mb_strlen($slug)>320||preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/',$slug)!==1)$errors[]='Slug must contain lowercase letters, numbers, and single hyphens only.';elseif($this->publications->slugExists($slug,$existingId))$errors[]='That publication slug is already in use.';if(trim((string)($input['project_id']??''))!==''&&($project===null||!$this->publications->relationExists('projects',$project)))$errors[]='Select a valid linked project.';if(trim((string)($input['research_unit_id']??''))!==''&&($unit===null||!$this->publications->relationExists('research_units',$unit)))$errors[]='Select a valid linked research unit.';$yearValue=trim((string)($input['publication_year']??''));$year=$yearValue===''?null:filter_var($yearValue,FILTER_VALIDATE_INT,['options'=>['min_range'=>1800,'max_range'=>(int)date('Y')+2]]);if($yearValue!==''&&$year===false){$errors[]='Publication year is outside the valid range.';$year=null;}$date=$this->date($input['publication_date']??null,$errors);if($date!==null&&$year!==null&&(int)substr($date,0,4)!==(int)$year)$errors[]='Publication date and publication year must agree.';$doi=$this->nullable($input['doi']??null);if($doi!==null){$doi=preg_replace('#^https?://(?:dx\.)?doi\.org/#i','',$doi)??$doi;if(mb_strlen($doi)>255||preg_match('#^10\.\d{4,9}/\S+$#i',$doi)!==1)$errors[]='Enter a valid DOI, for example 10.1000/example.';elseif($this->publications->doiExists($doi,$existingId))$errors[]='That DOI is already registered.';}$url=$this->nullable($input['external_url']??null);if($url!==null&&filter_var($url,FILTER_VALIDATE_URL)===false)$errors[]='Enter a valid external publication URL.';$access=(string)($input['access_type']??'unknown');if(!in_array($access,self::ACCESS,true))$errors[]='Choose a valid access type.';$abstract=$this->nullable($input['abstract']??null);if($abstract!==null&&mb_strlen($abstract)>100000)$errors[]='Abstract is too long.';$citation=$this->nullable($input['citation_text']??null);if($citation!==null&&mb_strlen($citation)>100000)$errors[]='Citation text is too long.';return['data'=>['publication_type_id'=>$type,'title'=>$title,'slug'=>$slug,'abstract'=>$abstract,'journal_name'=>$this->limited($input['journal_name']??null,255,'Journal name',$errors),'publisher'=>$this->limited($input['publisher']??null,255,'Publisher',$errors),'publication_year'=>$year,'publication_date'=>$date,'volume'=>$this->limited($input['volume']??null,50,'Volume',$errors),'issue'=>$this->limited($input['issue']??null,50,'Issue',$errors),'page_range'=>$this->limited($input['page_range']??null,50,'Page range',$errors),'doi'=>$doi,'isbn'=>$this->limited($input['isbn']??null,50,'ISBN',$errors),'external_url'=>$url,'access_type'=>$access,'citation_text'=>$citation],'project_id'=>$project,'research_unit_id'=>$unit,'errors'=>$errors];}
    /** @param list<string> $errors */ private function date(?string$value,array&$errors):?string{$v=trim((string)$value);if($v==='')return null;if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$v)!==1||strtotime($v)===false){$errors[]='Publication date must use YYYY-MM-DD.';return null;}return$v;}/** @param list<string> $errors */private function limited(?string$value,int$max,string$label,array&$errors):?string{$v=$this->nullable($value);if($v!==null&&mb_strlen($v)>$max)$errors[]="$label must be $max characters or fewer.";return$v;}private function nullable(?string$value):?string{$v=trim((string)$value);return$v===''?null:$v;}private function id(?string$value):?int{if($value===null||trim($value)==='')return null;$v=filter_var($value,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);return$v===false?null:(int)$v;}private function slugify(string$value):string{$ascii=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$value);$base=trim(strtolower((string)preg_replace('/[^a-zA-Z0-9]+/','-',$ascii===false?$value:$ascii)),'-');return mb_substr($base,0,300);}
}
